    const date = Date.parse(c.created_at);
    header.append(
      avatar,
      a,
      document.createTextNode(Number.isFinite(date) ? ' · ' + new Date(date).toLocaleString() : ''),
    );
    const body = el('div', 'body');
    const content = clean(c.html_body || '');
    content.querySelectorAll('.b-replies').forEach((n) => n.remove());
    body.append(...content.body.childNodes);
    const original = el('a', 'b-link', 'Ответить / действия в оригинале');
